          apiType: spec.name,
          baseUrl: spec.defaultBaseUrl,
          modelId: modelId,
          keyName: keyName,
        ),
      );
    } else {
      target
        ..modelId = modelId
        ..keyName = keyName;
    }
    _activeCustomName = name;
    io.writeln('saved provider $name (listed first in /provider)');
  }
  await _switchProvider(
    spec,
    spec.defaultBaseUrl,
    modelId,
    token: [REDACTED:Sensitive Value],
