        CustomProviderEntry(
          name: 'chatgpt',
          apiType: 'chatgpt',
          baseUrl: 'https://chatgpt.com/backend-api/codex',
          modelId: 'gpt-5',
          keyName: 'CHATGPT_OAUTH_CREDENTIALS',
        ),
