     final lower = name.toLowerCase();
     for (final entry in entries) {
       if (entry.name.toLowerCase() == lower) return entry;
     }
+    final canonical = canonicalProviderName(name);
+    for (final entry in entries) {
+      if (canonicalProviderName(entry.name) == canonical) return entry;
+    }
